<?php $provider=$provider??'payment';$authorization_url=$authorization_url??null;$token=$status_token??'';$id=(int)($transaction_id??0); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Processing | EduSasa</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fb}.wrap{max-width:620px;margin:50px auto;padding:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:25px;text-align:center}a,button{display:inline-block;padding:11px 16px;border-radius:8px;background:#172033;color:#fff;text-decoration:none;border:0;margin-top:12px}</style></head><body><main class="wrap"><section class="card"><h1>Payment started</h1><p><?= htmlspecialchars((string)$message) ?></p><?php if($authorization_url): ?><a href="<?= htmlspecialchars($authorization_url,ENT_QUOTES) ?>">Continue to secure checkout</a><?php endif; ?><p><button onclick="checkStatus()">Check payment status</button></p><p id="status">Status: pending</p></section></main><script>async function checkStatus(){const r=await fetch('/pay/status/<?= $id ?>?token=<?= rawurlencode($token) ?>');const d=await r.json();document.getElementById('status').textContent='Status: '+d.status+(d.message?' — '+d.message:'');if(d.status==='pending')setTimeout(checkStatus,5000)}setTimeout(checkStatus,5000)</script></body></html>
